import { afterEach, describe, expect, it, vi } from "vitest";
import { createHmac } from "node:crypto";

import { validateWebhookSignature } from "@/lib/webhook/signature";

afterEach(() => {
  vi.unstubAllEnvs();
});

function sign(body: string, secret: string): string {
  return createHmac("sha256", secret).update(body, "utf8").digest("hex");
}

describe("validateWebhookSignature", () => {
  it("retorna missing_secret quando WEBHOOK_SECRET não está definido", async () => {
    vi.stubEnv("WEBHOOK_SECRET", "");
    const result = await validateWebhookSignature('{"a":1}', "abc");
    expect(result).toBe("missing_secret");
  });

  it("retorna missing_signature quando o header não existe", async () => {
    vi.stubEnv("WEBHOOK_SECRET", "segredo");
    const result = await validateWebhookSignature('{"a":1}', null);
    expect(result).toBe("missing_signature");
  });

  it("retorna valid para assinatura correta do corpo bruto", async () => {
    vi.stubEnv("WEBHOOK_SECRET", "segredo");
    const body = '{"a":1}';
    const sig = sign(body, "segredo");
    expect(await validateWebhookSignature(body, sig)).toBe("valid");
  });

  it("retorna invalid para assinatura incorreta", async () => {
    vi.stubEnv("WEBHOOK_SECRET", "segredo");
    expect(await validateWebhookSignature('{"a":1}', "abcd")).toBe("invalid");
  });

  it("retorna invalid para assinatura válida de outro corpo", async () => {
    vi.stubEnv("WEBHOOK_SECRET", "segredo");
    const sig = sign('{"a":2}', "segredo");
    expect(await validateWebhookSignature('{"a":1}', sig)).toBe("invalid");
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";

import { checkRateLimit } from "@/lib/middleware/rate-limit";

afterEach(() => {
  vi.useRealTimers();
});

describe("checkRateLimit", () => {
  it("permite requisições dentro do limite", () => {
    const key = `test-${Math.random()}`;
    expect(checkRateLimit(key, { limit: 2, windowMs: 1000 })).toBe(true);
    expect(checkRateLimit(key, { limit: 2, windowMs: 1000 })).toBe(true);
  });

  it("bloqueia ao ultrapassar o limite", () => {
    const key = `test-${Math.random()}`;
    const cfg = { limit: 1, windowMs: 1000 };
    expect(checkRateLimit(key, cfg)).toBe(true);
    expect(checkRateLimit(key, cfg)).toBe(false);
  });

  it("redefine a janela após o tempo de reset", () => {
    vi.useFakeTimers();
    const key = `test-${Math.random()}`;
    const cfg = { limit: 1, windowMs: 1000 };
    expect(checkRateLimit(key, cfg)).toBe(true);
    expect(checkRateLimit(key, cfg)).toBe(false);
    vi.advanceTimersByTime(1001);
    expect(checkRateLimit(key, cfg)).toBe(true);
  });
});

import { describe, expect, it } from "vitest";

import { fromCsv, toCsv } from "@/lib/csv";

describe("toCsv", () => {
  it("gera cabeçalho e linhas", () => {
    const csv = toCsv([
      { sku: "A-1", qty: 2 },
      { sku: "B-2", qty: 5 },
    ]);
    expect(csv).toBe("sku,qty\nA-1,2\nB-2,5");
  });

  it("escapa aspas e vírgulas em campos", () => {
    const csv = toCsv([{ name: 'Rosa, "Blush"', qty: 1 }]);
    expect(csv).toContain('"Rosa, ""Blush"""');
  });
});

describe("fromCsv", () => {
  it("converte cabeçalho + linhas em objetos", () => {
    const rows = fromCsv("sku,qty\nA-1,2\nB-2,5");
    expect(rows).toEqual([
      { sku: "A-1", qty: "2" },
      { sku: "B-2", qty: "5" },
    ]);
  });

  it("lida com CRLF e campos entre aspas", () => {
    const rows = fromCsv('nome,valor\r\n"Rosa, Blush",10');
    expect(rows).toEqual([{ nome: "Rosa, Blush", valor: "10" }]);
  });

  it("retorna array vazio para entrada vazia", () => {
    expect(fromCsv("")).toEqual([]);
  });
});

import { describe, expect, it } from "vitest";

import {
  APP_ROLES,
  PERMISSIONS,
  PLATFORM_MODULES,
  ROLE_LABELS,
} from "@/lib/rbac";

describe("rbac", () => {
  it("define os papéis iniciais da plataforma", () => {
    expect(APP_ROLES).toEqual([
      "admin",
      "gestor",
      "financeiro",
      "estoque",
      "producao",
      "comercial",
      "marketplace",
    ]);
  });

  it("tem rótulo para todos os papéis", () => {
    for (const role of APP_ROLES) {
      expect(typeof ROLE_LABELS[role]).toBe("string");
      expect(ROLE_LABELS[role].length).toBeGreaterThan(0);
    }
  });

  it("não declara módulo operacional como disponível antes de existir", () => {
    const opcionais = PLATFORM_MODULES.filter(
      (m) => !["dashboard", "administracao"].includes(m.key),
    );
    for (const mod of opcionais) {
      expect(mod.status).toBe("coming_soon");
    }
  });

  it("expõe a permissão de edição da matriz", () => {
    expect(PERMISSIONS.permissionsManage).toBe("permissions.manage");
  });
});
